private void SetImageToStore(Dictionary<string, ImageData> store, Apps.XmlParser.Object obj, ValueEventArgs valueEventArgs)
{
	if (SelectedImage?.DisplayObject == obj)
	{
		ImageData imageData = valueEventArgs.Value as ImageData;
		if (store.ContainsKey("SelectedImage"))
		{
			store["SelectedImage"] = imageData;
		}
		else
		{
			store.Add("SelectedImage", imageData);
		}
		if (imageData != null && SelectedImage != null)
		{
			imageData.Tag = SelectedImage.DisplayName;
		}
	}
	else
	{
		string text = (obj.Owner as IVmModule).Name + "." + AppLocalizationService.GetLang(obj.Name);
		if (CheckImagesName != null && CheckImagesName.Contains(text))
		{
			if (store.ContainsKey(text))
			{
				store[text] = valueEventArgs.Value as ImageData;
			}
			else
			{
				store.Add(text, valueEventArgs.Value as ImageData);
			}
		}
	}
	if (SelectedInputImage?.DisplayObject == obj)
	{
		if (store.ContainsKey("SelectedInputImage"))
		{
			store["SelectedInputImage"] = valueEventArgs.Value as ImageData;
		}
		else
		{
			store.Add("SelectedInputImage", valueEventArgs.Value as ImageData);
		}
	}

public sealed class GrayImage:IImageData
{
    private readonly byte[] pixels;
    public int Width { get; }
    public int Height { get; }
    public int Stride=>Width;
    public ImagePixelFormat Format=>ImagePixelFormat.Mono8;
    public ReadOnlySpan<byte> Pixels => pixels;
    public byte this[int x, int y] => pixels[Offset(x, y)];
    private int Offset(int x, int y)
    {
        if ((uint)x >= (uint)Width || (uint)y >= (uint)Height) throw new ArgumentOutOfRangeException();
        return y * Width + x;
    }
    public GrayImage(int width, int height, ReadOnlySpan<byte> data)
    {
        if (width <= 0 || height <= 0) throw new ArgumentOutOfRangeException(nameof(width));
        if (data.Length != checked(width * height)) throw new ArgumentException("Pixel count must equal width * height.", nameof(data));
        Width = width; Height = height; pixels = data.ToArray();
    }
}

public sealed class RgbImage:IImageData {
 readonly byte[] pixels;
 public int Width {get;}
 public int Height {get;}
 public int Stride=>checked(Width*3);
 public ImagePixelFormat Format=>ImagePixelFormat.Rgb24;
 public ReadOnlySpan<byte> Pixels=>pixels;
 public RgbImage(int width,int height,ReadOnlySpan<byte> data){
  if(width<=0||height<=0)throw new ArgumentOutOfRangeException(nameof(width));
  if(data.Length!=checked(width*height*3))throw new ArgumentException("RGB24 data must contain width * height * 3 bytes.",nameof(data));
  Width=width;Height=height;pixels=data.ToArray();
 }
}

public sealed class RawImage:IImageData {
 readonly byte[] pixels;
 public int Width{get;}
 public int Height{get;}
 // Zero means that the transport supplied no packed-row stride (for example planar data).
 public int Stride{get;}
 public ImagePixelFormat Format{get;}
 public ReadOnlySpan<byte> Pixels=>pixels;
 public RawImage(int width,int height,ImagePixelFormat format,ReadOnlySpan<byte> data,int stride=0){
  if(width<=0||height<=0||stride<0||data.IsEmpty)throw new ArgumentOutOfRangeException(nameof(width));
  Width=width;Height=height;Format=format;Stride=stride;pixels=data.ToArray();
 }
}

